import{_ as t,o as s,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const v=JSON.parse('{"title":"Candidature et admission","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apprenant/candidature.md","filePath":"src/guide/apprenant/candidature.md"}'),o={name:"guide/apprenant/candidature.md"};function a(i,e,u,d,l,c){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="candidature-et-admission" tabindex="-1">Candidature et admission <a class="header-anchor" href="#candidature-et-admission" aria-label="Permalink to &quot;Candidature et admission&quot;">​</a></h1><p>Avant d&#39;être apprenant, on est candidat. L&#39;admission se fait en quatre étapes, toujours dans cet ordre : <strong>dépôt</strong>, <strong>entretien</strong>, <strong>test</strong>, <strong>décision</strong>.</p><h2 id="_1-deposer-sa-candidature" tabindex="-1">1. Déposer sa candidature <a class="header-anchor" href="#_1-deposer-sa-candidature" aria-label="Permalink to &quot;1. Déposer sa candidature&quot;">​</a></h2><p>Le dépôt se fait sur le site NextBoxx : vous choisissez un référentiel publié (la formation), le <strong>format</strong> qui vous convient (distanciel, hybride ou présentiel), et vous joignez votre dossier. Le site transmet votre candidature à Kura.</p><ul><li>Votre compte NextBoxx est créé s&#39;il n&#39;existe pas, ou réutilisé s&#39;il existe déjà pour votre adresse e-mail.</li><li>Vous recevez un accusé de réception. Pour un nouveau compte, il contient le lien pour <a href="./../premiers-pas.html#creer-votre-compte">choisir votre mot de passe</a>, valable 7 jours.</li><li>Vous n&#39;avez qu&#39;<strong>une candidature en cours à la fois</strong>, quelle que soit la formation.</li></ul><p>Vous suivez ensuite votre dossier dans Kura, rubrique <strong>Parcours → Ma candidature</strong> : l&#39;étape en cours, les dates, votre score au test et la décision. Les comptes rendus internes de l&#39;équipe n&#39;y figurent pas.</p><div class="tip custom-block"><p class="custom-block-title">Candidat mineur</p><p>Si vous êtes mineur, votre dossier est signalé dès le dépôt. Votre inscription ne pourra aboutir qu&#39;avec le consentement et la signature d&#39;un représentant légal (voir <a href="./inscription.html#si-vous-etes-mineur">Inscription et convention</a>).</p></div><h2 id="_2-l-entretien" tabindex="-1">2. L&#39;entretien <a class="header-anchor" href="#_2-l-entretien" aria-label="Permalink to &quot;2. L&#39;entretien&quot;">​</a></h2><p>Un conseiller admissions prend votre dossier en charge et devient votre interlocuteur. Il mène un entretien avec vous, en principe <strong>dans les 5 jours ouvrés</strong> qui suivent le dépôt (du lundi au vendredi, hors jours fériés).</p><p>À la clôture de l&#39;entretien, vous recevez par e-mail le lien du test.</p><h2 id="_3-le-test-d-admission" tabindex="-1">3. Le test d&#39;admission <a class="header-anchor" href="#_3-le-test-d-admission" aria-label="Permalink to &quot;3. Le test d&#39;admission&quot;">​</a></h2><p>Le test est un QCM, accessible avec le lien reçu, <strong>sans connexion</strong>. Quelques règles à connaître avant de commencer :</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Lien</td><td>À usage unique, valable <strong>48 heures</strong> pour commencer</td></tr><tr><td>Tentatives</td><td><strong>2</strong> au plus</td></tr><tr><td>Durée</td><td><strong>45 minutes</strong> par tentative, à partir de l&#39;ouverture du QCM</td></tr><tr><td>Questions</td><td>10, tirées d&#39;une banque de 20 questions validées. La 2ᵉ tentative propose d&#39;autres questions que la 1ʳᵉ</td></tr></tbody></table><p>À 45 minutes, les réponses déjà données sont envoyées telles quelles ; la tentative compte comme utilisée. Votre <strong>score s&#39;affiche dès l&#39;envoi</strong>.</p><p>Le seuil de réussite est de <strong>6 bonnes réponses sur 10</strong>. Une tentative réussie clôt le test ; sinon il se clôt après la 2ᵉ tentative. Le score est <strong>indicatif</strong> : votre dossier passe en décision quel que soit le résultat, et c&#39;est le conseiller qui décide.</p><p>Si le lien a expiré, ou si vos tentatives sont épuisées faute de temps, l&#39;équipe est relancée. Le conseiller peut vous envoyer un nouveau lien (vos tentatives sont alors remises à zéro) ou clore le test.</p><h2 id="_4-la-decision" tabindex="-1">4. La décision <a class="header-anchor" href="#_4-la-decision" aria-label="Permalink to &quot;4. La décision&quot;">​</a></h2><p>Le conseiller rend sa décision, <strong>motivée</strong>, dans les 3 jours ouvrés qui suivent le test. Vous la recevez par e-mail, avec une <strong>lettre de décision</strong> en PDF. Vous la retrouvez aussi dans <strong>Ma candidature</strong> et dans <strong>Mes documents</strong>. Le motif du conseiller reste interne.</p><ul><li><strong>Admis.</strong> Votre compte devient un compte <strong>Apprenant</strong> et votre inscription est créée. Le conseiller a pu vous placer dans une cohorte ; sinon, le Coordinateur pédagogique vous y affecte plus tard et vous prévient par e-mail. La suite est dans <a href="./inscription.html">Inscription et convention</a>.</li><li><strong>Refusé.</strong> Le dossier est clos. Aucun paiement n&#39;est dû et aucun accès à Sève n&#39;est ouvert.</li></ul><h3 id="postuler-de-nouveau-apres-un-refus" tabindex="-1">Postuler de nouveau après un refus <a class="header-anchor" href="#postuler-de-nouveau-apres-un-refus" aria-label="Permalink to &quot;Postuler de nouveau après un refus&quot;">​</a></h3><p>Vous pouvez déposer un nouveau dossier <strong>7 jours</strong> après un refus. Il est rattaché à votre compte et lié au précédent, qui reste visible dans l&#39;historique. Pour le nouveau test, les questions de la première tentative de votre test précédent sont écartées du tirage autant que la banque le permet.</p><p>Un dossier refusé est conservé 12 mois, puis <strong>anonymisé</strong> : seuls le référentiel, le format, les dates, les scores et la décision subsistent, pour les statistiques. La motivation, les pièces jointes, les comptes rendus, les réponses au test et le motif sont supprimés, et le dossier est détaché de votre compte.</p>',22)])])}const m=t(o,[["render",a]]);export{v as __pageData,m as default};
